const service = new FulfilmentService(new InMemoryProductRepository(), new InMemoryOrderRepository());
const app = createHttpServer(service);
const port = Number(process.env.PORT ?? 3000);

app.listen(port, () => {
  console.log(`Order fulfilment API listening on port ${port}`);
